INSERT INTO `wp_josinbryh5_postmeta` VALUES (10461,1086,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_title','Project Management');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (10462,1086,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (10463,1086,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_text','How do you eat an elephant? Proper project management. Website projects and initiatives can be daunting in size and scope. In my experience, the end result is mainly dictated planning and communication with the client and the team. I am well practiced in managing projects and looking for inefficiencies to solve for with detailed processes and documentation. Why create the wheel twice?');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (10464,1086,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_text','field_68814735d6970');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (10465,1086,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_4_title','Technical Debt Management');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (10466,1086,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_4_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (10467,1086,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_4_text','As a site ages, it typically gets dragged down by increased technical debt. Whether this is from day one with minimizing development time by increasing page write time, or adding dependencies to add new features all the developer choices add up. As a developer, I think about the long term for a solution and how it effects this growing debt. Taking the time to make a thoughtful solution will keep t');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (10468,1086,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_4_text','field_68814735d6970');
