INSERT INTO `wp_josinbryh5_postmeta` VALUES (16543,1142,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_0_title','CMS Development');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16544,1142,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_0_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16545,1142,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_0_text','Well built Content Management Systems (CMS) are the best way to empower users and team members to own their own content and make updates without breaking their site. I specialize in crafting efficient CMS systems that are not only easy for the content mangers, but the developers as well. By creating great Gutenberg Blocks or Advanced Custom Fields, content can be changed at any time. ');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16546,1142,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_0_text','field_68814735d6970');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16547,1142,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_1_title','Team Collaboration');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16548,1142,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_1_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16549,1142,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_1_text','Teamwork makes the dreamwork! Nobody can do it all by themselves. Normally there are other stakeholders in the room that have plans or expertise to tap into. As a developer, I know I am not the best designer or copywriter. My job is to work with my team to build the best tools possible to align with my teams needs. ');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16550,1142,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_1_text','field_68814735d6970');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16551,1142,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_2_title','Accessibility');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16552,1142,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_2_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16553,1142,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_2_text','The internet and the websites on it has become an essential point of contact for all people, whether they are visually impaired or have perfect vision. Because of this, developers need to follow specific guidelines to communicate to all visitors. Some things are simple and straightforward like color contrast and descriptive link text. ');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (16554,1142,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_2_text','field_68814735d6970');
