INSERT INTO `wp_josinbryh5_postmeta` VALUES (17542,1144,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (17543,1144,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_text','How do you eat an elephant? Proper project management. Website projects and initiatives can be daunting in size and scope. In my experience, the end result is mainly dictated planning and communication with the client and the team. I am well practiced in managing projects and looking for inefficiencies to solve for with detailed processes and documentation. Why create the wheel twice?');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (17544,1144,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_text','field_68814735d6970');
