INSERT INTO `wp_josinbryh5_postmeta` VALUES (18981,1148,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_1_text','Teamwork makes the dreamwork! Nobody can do it all by themselves. Normally there are other stakeholders in the room that have plans or expertise to tap into. As a developer, I know I am not the best designer or copywriter. My job is to work with my team to build the best tools possible to align with my teams needs. ');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (18982,1148,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_1_text','field_68814735d6970');
