INSERT INTO `wp_josinbryh5_postmeta` VALUES (19513,1150,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_0_title','CMS Development');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (19514,1150,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_0_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (19515,1150,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_0_text','Well built Content Management Systems (CMS) are the best way to empower users and team members to own their own content and make updates without breaking their site. I specialize in crafting efficient CMS systems that are not only easy for the content mangers, but the developers as well. By creating great Gutenberg Blocks or Advanced Custom Fields, content can be changed at any time. ');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (19516,1150,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_0_text','field_68814735d6970');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (19517,1150,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_1_title','Team Collaboration');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (19518,1150,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_1_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (19519,1150,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_1_text','Teamwork makes the dreamwork! Nobody can do it all by themselves. Normally there are other stakeholders in the room that have plans or expertise to tap into. As a developer, I know I am not the best designer or copywriter. My job is to work with my team to build the best tools possible to align with my teams needs. ');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (19520,1150,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_1_text','field_68814735d6970');
