INSERT INTO `wp_josinbryh5_postmeta` VALUES (22968,1158,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_5_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (22969,1158,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_5_text','To put in plainly, I get results. Whether it\'s carefully crafted designs to make accessible and pixel perfect, or a vague desire for content to do something I can make it happen. Over the course of my 10 years of development I\'ve launched around 100 sites. Not all of them are created equally, and the solutions I\'ve built has improves dramatically over the years.\r\n\r\nExamples:\r\n<ul>\r\n 	<li>\r\n<p class=\"p1\"><a href=\"https://www.injuryak.com/\" target=\"_blank\" rel=\"noopener\">https://www.injuryak.com/</a></p>\r\n</li>\r\n 	<li>\r\n<p class=\"p1\"><a href=\"https://griswoldlasalle.com/\" target=\"_blank\" rel=\"noopener\">https://griswoldlasalle.com/</a></p>\r\n</li>\r\n 	<li>\r\n<p class=\"p1\"><a href=\"https://www.dankolaw.com/\" target=\"_blank\" rel=\"noopener\">https://www.dankolaw.com/</a></p>\r\n</li>\r\n 	<li>\r\n<p class=\"p1\"><a href=\"https://www.lawpoweredbywomen.com/\" target=\"_blank\" rel=\"noopener\">https://www.lawpoweredbywomen.com/</a></p>\r\n</li>\r\n 	<li>\r\n<p class=\"p1\"><a href=\"https://dawson.com/\" target=\"_blank\" rel=\"noopener\">https://dawson.com/</a></p>\r\n</li>\r\n 	<li>\r\n<p class=\"p1\"><a href=\"https://cphlibrary.org/\" target=\"_blank\" rel=\"noopener\">https://cphlibrary.org/</a></p>\r\n</li>\r\n</ul>');
