INSERT INTO `wp_josinbryh5_postmeta` VALUES (23902,1160,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (23903,1160,'flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_text','How do you eat an elephant? Proper project management. Website projects and initiatives can be daunting in size and scope. In my experience, the end result is mainly dictated planning and communication with the client and the team. I am well practiced in managing projects and looking for inefficiencies to solve for with detailed processes and documentation. Why create the wheel twice?');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (23904,1160,'_flex_voyager_1_column_rep_1_flex_content_0_block_accordion_group_rep_3_text','field_68814735d6970');
