INSERT INTO `wp_josinbryh5_postmeta` VALUES (27952,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_0_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27953,1173,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_0_text','Well built Content Management Systems (CMS) are the best way to empower users and team members to own their own content and make updates without breaking their site. I specialize in crafting efficient CMS systems that are not only easy for the content mangers, but the developers as well. By creating great Gutenberg Blocks or Advanced Custom Fields, content can be changed at any time. ');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27954,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_0_text','field_68814735d6970');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27955,1173,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_1_title','Team Collaboration');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27956,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_1_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27957,1173,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_1_text','Teamwork makes the dreamwork! Nobody can do it all by themselves. Normally there are other stakeholders in the room that have plans or expertise to tap into. As a developer, I know I am not the best designer or copywriter. My job is to work with my team to build the best tools possible to align with my teams needs. ');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27958,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_1_text','field_68814735d6970');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27959,1173,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_2_title','Accessibility');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27960,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_2_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27961,1173,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_2_text','The internet and the websites on it has become an essential point of contact for all people, whether they are visually impaired or have perfect vision. Because of this, developers need to follow specific guidelines to communicate to all visitors. Some things are simple and straightforward like color contrast and descriptive link text. ');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27962,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_2_text','field_68814735d6970');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27963,1173,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_3_title','Project Management');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27964,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_3_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27965,1173,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_3_text','How do you eat an elephant? Proper project management. Website projects and initiatives can be daunting in size and scope. In my experience, the end result is mainly dictated planning and communication with the client and the team. I am well practiced in managing projects and looking for inefficiencies to solve for with detailed processes and documentation. Why create the wheel twice?');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27966,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_3_text','field_68814735d6970');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27967,1173,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_4_title','Technical Debt Management');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27968,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_4_title','field_68814735d696f');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27969,1173,'flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_4_text','As a site ages, it typically gets dragged down by increased technical debt. Whether this is from day one with minimizing development time by increasing page write time, or adding dependencies to add new features all the developer choices add up. As a developer, I think about the long term for a solution and how it effects this growing debt. Taking the time to make a thoughtful solution will keep the site healthy until the design dictates the change.');
INSERT INTO `wp_josinbryh5_postmeta` VALUES (27970,1173,'_flex_voyager_1_column_rep_0_flex_content_0_block_accordion_group_rep_4_text','field_68814735d6970');
